public class Main {
    public static void main(String[] args) {
        String[] data = {"12", "7", "x", "20"};
        int total = 0;
        int dilewati = 0;
        for (String d : data) {
            try {
                total += Integer.parseInt(d);
            } catch (NumberFormatException e) {
                dilewati++;
            }
        }
        System.out.println(total);
        System.out.println(dilewati);
    }
}

